/**
 * The map of Iran the projects page draws, as plain SVG path data.
 *
 * WHY THIS IS NOT GOOGLE MAPS / MAPBOX. A tile service is the obvious answer
 * and the wrong one here: Google Maps and Mapbox are both unreachable from
 * inside Iran, both need an API key and a billing account, and both would put
 * the site's primary visual on a third-party request that fails for exactly
 * the audience this site is for. Everything below is self-hosted and renders
 * with no network call at all.
 *
 * SOURCES. The thirty-one province outlines come from the `iran-geojson`
 * package (1.0.0); the surrounding countries from Natural Earth via
 * `world-atlas` (2.0.2, countries-10m). Both are projected here at build time
 * — Mercator, framed on Iran — and simplified to a ~1.6px tolerance, which is
 * invisible at the sizes the page draws and keeps the payload to ~60KB of
 * path data that gzips well. Neither package ships in the bundle.
 *
 * To reproject or reframe, regenerate: the constants below and the path data
 * must stay in step, because `project()` is what puts the markers on the
 * coastline rather than in the sea.
 */

/** The projection's frame, in degrees. */
export const MAP = {
  width: 1000,
  height: 922,
  lon0: 43.0, lon1: 64.0, lat0: 24.0, lat1: 40.3,
} as const

/**
 * Longitude/latitude to the SVG's own user units. Mercator, matching the
 * projection the paths were generated with — change one and you must change
 * the other.
 */
export function project(lon: number, lat: number): { x: number, y: number } {
  const merc = (la: number) => Math.log(Math.tan(Math.PI / 4 + (la * Math.PI / 180) / 2))
  const x0 = MAP.lon0 * Math.PI / 180
  const x1 = MAP.lon1 * Math.PI / 180
  const y1 = merc(MAP.lat1)
  const k = MAP.width / (x1 - x0)
  return {
    x: ((lon * Math.PI / 180) - x0) * k,
    y: (y1 - merc(lat)) * k,
  }
}

export interface Province { id: string, name: string, d: string }

